solution:
fn safe_swap(arr: &mut Vec[Int], i: Int, j: Int)
  requires: i >= 0;
  requires: i < arr.len();
  requires: j >= 0;
  requires: j < arr.len();
{
  let temp = arr[i];
  arr[i] = arr[j];
  arr[j] = temp;
}

fn main() -> Int {
  let v = Vec[Int]();
  v.push(10); v.push(20); v.push(30);
  safe_swap(&mut v, 0, 2);
  return v[0];
}
